pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(uint256 newMin) internal {
        bool reverted;
        try c.SetMinSum(newMin) { reverted = false; } catch { reverted = true; }
        uint256 post;
        try c.MinSum() returns (uint256 __r) { post = __r; } catch { return; }
        assertTrue(reverted || post == newMin);
    }

    function testFuzz_run(uint256 newMin) public {
        _run(newMin);
    }

    receive() external payable {}
}
